// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, address(c).balance);
        vm.deal(address(c), amount);
        // The owner is immutable; we can read it before the call
        address owner = c.owner();
        uint256 balanceBefore = owner.balance;
        // Call go() with no msg.value; only the contract's balance may be used
        vm.prank(caller);
        c.go();
        uint256 balanceAfter = owner.balance;
        // In the reference: the remaining balance is sent to owner, so balanceAfter = balanceBefore + balance of c before go()
        // Since msg.value is 0 and the contract may have some balance from setup, the increase is exactly address(c).balance before call
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

