// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        amount = bound(amount, 0, address(c).balance);
        vm.deal(address(this), amount);
        vm.prank(sender);
        // Drive the contract by calling go with msg.value = amount
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.go.selector));
        // Only consider cases where the call to go succeeds (target call must not revert)
        vm.assume(success);
        // After a successful go(), the contract should have forwarded all ETH: the target got msg.value and the owner got the remaining balance
        assertTrue(address(c).balance == 0);
    }
}
